  it("queues Kimi ACP execution mode changes during active turns and flushes once", async () => {
    const events: AgentEvent[] = [];
    const { acpBackendId, registry, sendControlPrompt, sessions } =
      createKimiAcpRegistry({
        sessions: [
          {
            backendId: "acp:kimi" as AcpBackendId,
            sessionId: "kimi-session-1",
            title: "ACP session",
            createdAt: 1000,
            updatedAt: 1000,
            executionMode: "default",
            status: "idle",
          },
        ],
        sendControlPrompt: vi.fn(async () => ({
          text: "You only live once! All actions will be auto-approved.",
        })),
      });
    registry.onEvent((event) => {
      events.push(event);
    });

    await expect(
      registry.listThreads({ backend: acpBackendId }),
    ).resolves.toEqual([
      expect.objectContaining({
        id: "kimi-session-1",
        executionMode: "default",
      }),
    ]);

    await registry.startTurn({
      backend: acpBackendId,
      threadId: "kimi-session-1",
      input: [{ type: "text", text: "work" }],
    });

    await expect(
      registry.setThreadExecutionMode({
        backend: acpBackendId,
        threadId: "kimi-session-1",
        executionMode: "full-access",
      }),
    ).resolves.toEqual({
      backend: acpBackendId,
      threadId: "kimi-session-1",
      executionMode: "full-access",
    });
    expect(sendControlPrompt).not.toHaveBeenCalled();

    await (registry as unknown as { emit(event: AgentEvent): Promise<void> }).emit({
      backend: acpBackendId,
      notification: {
        method: "turn/completed",
        params: {
          threadId: "kimi-session-1",
          turnId: "turn-1",
          turn: {
            id: "turn-1",
            status: "completed",
            output: [],
          },
        },
      },
    });
    await vi.waitFor(() => {
      expect(sendControlPrompt).toHaveBeenCalledWith({
        sessionId: "kimi-session-1",
        prompt: "/yolo",
      });
      expect(sessions[0]?.executionMode).toBe("full-access");
    });

    await expect(
      registry.listThreads({ backend: acpBackendId }),
    ).resolves.toEqual([
      expect.objectContaining({
        id: "kimi-session-1",
        executionMode: "full-access",
      }),
    ]);
    const methods = events.map((event) => event.notification.method);
    expect(methods).toContain("thread/executionMode/queued");
    expect(methods).toContain("thread/executionMode/updated");
    expect(methods).toContain("thread/executionMode/queueCleared");

    await registry.close();
  });

  it("asks each ACP process to close idle sessions, keeping a thread with a live turn", async () => {
    const { acpBackendId, acpClient, registry } = createKimiAcpRegistry({
      sessions: [{
        backendId: "acp:kimi" as AcpBackendId,
        sessionId: "kimi-session-1",
        title: "ACP session",
        createdAt: 1000,
        updatedAt: 1000,
        executionMode: "default",
        status: "idle",
      }],
    });
    const closeIdleSessions = vi.fn(async (_params: {
      idleMs: number;
      isSessionBusy?: (sessionId: string) => boolean;
    }) => [] as string[]);
    Object.assign(acpClient, { closeIdleSessions });
    const busyDuringSweep = (sessionId: string) =>
      closeIdleSessions.mock.lastCall?.[0].isSessionBusy?.(sessionId);

    await registry.startTurn({
      backend: acpBackendId,
      threadId: "kimi-session-1",
      input: [{ type: "text", text: "work" }],
    });
    await registry.closeIdleAcpSessions();

    expect(closeIdleSessions).toHaveBeenCalledTimes(1);
    expect(closeIdleSessions.mock.lastCall?.[0].idleMs).toBe(10 * 60_000);
    expect(busyDuringSweep("kimi-session-1")).toBe(true);
    expect(busyDuringSweep("kimi-session-2")).toBe(false);

    await emitCompletedTurn(registry, acpBackendId, "kimi-session-1");
    await registry.closeIdleAcpSessions();

    expect(closeIdleSessions).toHaveBeenCalledTimes(2);
    expect(busyDuringSweep("kimi-session-1")).toBe(false);

    await registry.close();
    // A closed registry starts no sweep.
    await registry.closeIdleAcpSessions();
    expect(closeIdleSessions).toHaveBeenCalledTimes(2);
  });

